def test_deprecation_and_server_warnings_show_once_per_process() -> None:
    marked = {
        "Deprecation": "@1767225600",
        "Sunset": "Thu, 31 Dec 2026 00:00:00 GMT",
        "x-dfo-warning": "Anonymous builds share a small quota; create a free key.",
    }
    recorder = Recorder(*(httpx2.Response(200, headers=marked) for _ in range(3)))
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        with make(recorder) as transport:
            transport.request("GET", "/datasets/schema")
            transport.request("GET", "/datasets/schema")
        with make(recorder) as other:
            other.request("GET", "/datasets/schema")
    categories = sorted(type(warning.message).__name__ for warning in caught)
    assert categories == ["DfoDeprecationWarning", "DfoWarning"]
    texts = [str(warning.message) for warning in caught]
    assert marked["x-dfo-warning"] in texts
    assert issubclass(DfoDeprecationWarning, DfoWarning)


def test_server_text_loses_terminal_and_bidi_controls() -> None:
    steer = "\x1b]0;PWNED\x07\x1b[2J"
    detail = f"Bad{steer}\u202e\x9b input."
    refusal = problem(400, code="request_invalid", detail=detail)
    refusal.headers["x-dfo-warning"] = f"Quota{steer} low."
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        with make(Recorder(refusal)) as transport:
            with pytest.raises(InvalidRequestError) as refused:
                transport.request("GET", "/datasets/schema")
    texts = [str(refused.value), refused.value.detail, str(caught[0].message)]
    assert texts == [
        "Bad]0;PWNED[2J input. (request_invalid)",
        "Bad]0;PWNED[2J input.",
        "Quota]0;PWNED[2J low.",
    ]


